    m = validate(fid, panel)
    if m is None:
        print(f"{fid}: INSUFFICIENT -> skip", flush=True)
        results[fid] = {'ok': False, 'metrics': {'error': 'insufficient'}}
        json.dump(results, open('scripts/miner_3_20260730_results_round17.json', 'w'), indent=1, default=str)
        continue
